-- ---------------------------------------------------------------
-- V1: the product table - the SINGLE SOURCE OF TRUTH for product data.
-- Debezium captures every committed change to this table from the binlog.
-- Rules for future changes (they reach the CDC stream too):
--   * never edit this file after it ran; add V2__..., V3__...
--   * prefer ADDING nullable columns; coordinate renames/removals with the
--     read-side projector (product-service) before deploying them.
-- ---------------------------------------------------------------
CREATE TABLE product
(
    -- UUID generated by the application: the SAME id is used in Elasticsearch
    id          VARCHAR(36)   NOT NULL,
    sku         VARCHAR(50)   NOT NULL,
    name        VARCHAR(200)  NOT NULL,
    description VARCHAR(2000) NULL,
    brand       VARCHAR(100)  NOT NULL,
    category    VARCHAR(100)  NOT NULL,
    price       DECIMAL(12, 2) NOT NULL,
    ram_gb      INT           NULL,
    rating      DOUBLE        NULL,
    -- Comma-separated, lower-case tags ("gaming,rtx"). Keeping them in this row
    -- means ONE table = ONE change event per product write (no multi-table joins in CDC).
    tags        VARCHAR(700)  NULL,
    -- Optimistic-locking counter; also the external version of the Elasticsearch document
    version     BIGINT        NOT NULL DEFAULT 0,
    created_at  DATETIME(6)   NOT NULL,
    updated_at  DATETIME(6)   NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_product_sku UNIQUE (sku),
    CONSTRAINT ck_product_price CHECK (price > 0),
    CONSTRAINT ck_product_ram CHECK (ram_gb IS NULL OR ram_gb BETWEEN 1 AND 1024),
    CONSTRAINT ck_product_rating CHECK (rating IS NULL OR rating BETWEEN 0 AND 5)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;
